        int c = scanner.nextInt();
        int d = scanner.nextInt();
        int p = scanner.nextInt();
        int nl = scanner.nextInt();
        int np = scanner.nextInt();

        // Total milliliters of drink
        long totalDrink = (long) k * l;
        // Total slices of lime
        long totalLime = (long) c * d;
        // Total grams of salt
        long totalSalt = (long) p;

        // Number of toasts possible with each ingredient
        long toastsFromDrink = totalDrink / nl;
        long toastsFromLime = totalLime; // each toast needs 1 slice
        long toastsFromSalt = totalSalt / np;

        // Minimum number of toasts possible overall
        long minToasts = Math.min(toastsFromDrink, Math.min(toastsFromLime, toastsFromSalt));

        // Each friend makes the same number of toasts
        long toastsPerFriend = minToasts / n;

        System.out.println(toastsPerFriend);

        scanner.close();
    }
}
