        long minToasts = Math.min(toastsByDrink, Math.min(toastsByLimes, toastsBySalt));

        // Each friend makes the same number of toasts
        long toastsPerFriend = minToasts / n;

        System.out.println(toastsPerFriend);

        scanner.close();
