        long toastsFromDrink = totalDrink / nl;

        // Total lime slices
        long totalLimeSlices = (long) c * d;
        // Number of toasts possible with lime
        long toastsFromLime = totalLimeSlices;

        // Number of toasts possible with salt
        long toastsFromSalt = p / np;

        // Total toasts possible (limited by the scarcest resource)
        long totalToasts = Math.min(Math.min(toastsFromDrink, toastsFromLime), toastsFromSalt);

        // Each friend gets an equal number of toasts
        long toastsPerFriend = totalToasts / n;

        System.out.println(toastsPerFriend);

        scanner.close();
    }
}
